/**
 * Typed access layer for the verified chart data in `ym-data.json`.
 *
 * The JSON itself is generated by `scripts/export_visual_data.py` in the
 * repository root and must not be edited by hand. `resolveJsonModule` is on,
 * so the raw JSON is imported directly and re-exported with precise types.
 */
import raw from "./ym-data.json";

export type Phase2 = {
  beta0rig: number;
  N: number;
  kpScan: {
    beta: number[];
    /** `null` past index 38 — the Kadanoff-Pfeuty bound is vacuous there. */
    kp: (number | null)[];
  };
  gapBound: {
    beta: number[];
    /** -log(A + tail); 38 valid points. */
    gap: number[];
  };
  polymerSizes: {
    size: number[];
    count: number[];
  };
};

export type Phase3 = {
  trajectory: {
    step: number[];
    beta: number[];
    gap: number[];
  };
};

export type Phase4 = {
  /** SU(3) mass gap at beta = 0: log 3. */
  gapSU3: number;
  /** Dimensions of the low-lying SU(3) irreps, ascending. */
  dims: number[];
};

export type Phase5 = {
  betas: number[];
  corr: {
    t: number[];
    beta1: number[];
    beta1_se: number[];
    beta2: number[];
    beta2_se: number[];
  };
  osz: {
    beta1: number[];
    beta2: number[];
  };
  plaquette: {
    beta1: number;
    beta2: number;
  };
};

export type YmData = {
  generated: string;
  phase2: Phase2;
  phase3: Phase3;
  phase4: Phase4;
  phase5: Phase5;
};

export const ymData = raw as unknown as YmData;

/** Convenience aliases for the sections used most often in the charts. */
export const phase2 = ymData.phase2;
export const phase3 = ymData.phase3;
export const phase4 = ymData.phase4;
export const phase5 = ymData.phase5;

/** log 2 — the exact SU(2) mass gap at beta = 0. */
export const LOG2 = Math.log(2);
/** log 3 — the exact SU(3) mass gap at beta = 0. */
export const LOG3 = Math.log(3);
/** Declared in the JSON so the chart and the prose cannot drift apart. */
export const BETA0_RIG = ymData.phase2.beta0rig;
/** Autocorrelation strength measured by the Phase 5 Monte Carlo run. */
export const AUTOCORR = 0.0595;
